package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.kinetics.KineticGraph;
import com.simibubi.create.content.kinetics.belt.*;
import com.simibubi.create.content.kinetics.belt.item.BeltConnectorItem;
import com.simibubi.create.content.kinetics.belt.transport.*;
import com.simibubi.create.content.kinetics.simpleRelays.ShaftBlock;
import com.simibubi.create.content.logistics.depot.DepotBlockEntity;
import com.simibubi.create.content.logistics.tunnel.*;
import com.simibubi.create.content.logistics.tunnel.BrassTunnelBlockEntity.SelectionMode;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.fabricmc.fabric.api.transfer.v1.item.*;
import net.fabricmc.fabric.api.transfer.v1.transaction.Transaction;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.phys.*;

public class TunnelGameTests {
    private static final BlockPos P=new BlockPos(3,3,3),N=P.below().north(),S=P.below().south();
    private static BeltBlockEntity chain(GameTestHelper h,int z){var start=new BlockPos(1,2,z);var end=new BlockPos(3,2,z);h.setBlock(start,AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));h.setBlock(end,AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));h.assertTrue(BeltConnectorItem.createBelts(h.getLevel(),h.absolutePos(start),h.absolutePos(end)),"Belt created");for(int x=1;x<=3;x++){var belt=h.getBlockEntity(new BlockPos(x,2,z),BeltBlockEntity.class);belt.setCasingType(BeltBlockEntity.CasingType.ANDESITE);belt.setNetworkState(-64,-64,false,new KineticGraph.Stress(10000,0,false),Map.of());}return h.getBlockEntity(start,BeltBlockEntity.class);}
    private static BrassTunnelBlockEntity cross(GameTestHelper h){chain(h,3);h.setBlock(N,AllBlocks.DEPOT);h.setBlock(S,AllBlocks.DEPOT);h.setBlock(P.below().east(),Blocks.STONE);h.setBlock(P,AllBlocks.BRASS_TUNNEL.defaultBlockState().setValue(BeltTunnelBlock.HORIZONTAL_AXIS,Direction.Axis.X).setValue(BeltTunnelBlock.SHAPE,BeltTunnelBlock.Shape.CROSS));var tunnel=h.getBlockEntity(P,BrassTunnelBlockEntity.class);tunnel.updateTunnelConnections();return tunnel;}
    private static void insert(BrassTunnelBlockEntity tunnel,Item item,int count){try(var tx=Transaction.openOuter()){if(tunnel.accept(new ItemStack(item,count),Direction.WEST,tx)!=count)throw new AssertionError("Tunnel rejected test cargo");tx.commit();}}
    private static void tick(BrassTunnelBlockEntity tunnel,int ticks){for(int i=0;i<ticks;i++)tunnel.tickDistribution();}
    private static long count(GameTestHelper h,BlockPos pos,Item item){var depot=h.getBlockEntity(pos,DepotBlockEntity.class);return java.util.stream.Stream.concat(depot.inventory.inputs.stream(),depot.inventory.outputs.stream()).filter(slot->slot.stack().is(item)).mapToLong(slot->slot.getAmount()).sum();}
    private static void fill(GameTestHelper h,BlockPos pos,int count){var depot=h.getBlockEntity(pos,DepotBlockEntity.class);try(var tx=Transaction.openOuter()){depot.inventory.inputs.getFirst().insert(ItemVariant.of(Items.APPLE),count,tx);tx.commit();}}
    @GameTest public void splitSendsBalancedBatchesAndConservesRemainder(GameTestHelper h){var tunnel=cross(h);insert(tunnel,Items.APPLE,11);tick(tunnel,3);h.assertValueEqual(count(h,S,Items.APPLE),6L,"First output receives odd extra");h.assertValueEqual(count(h,N,Items.APPLE),5L,"Other output receives five");h.assertTrue(tunnel.getStackToDistribute().isEmpty(),"Owned queue consumed once");h.succeed();}
    @GameTest(maxTicks=90) public void splitSkipsBlockedOutputsAndRedistributesPartialCapacity(GameTestHelper h){
        var tunnel=cross(h);h.setBlock(S,AllBlocks.WEIGHTED_EJECTOR.defaultBlockState().setValue(com.simibubi.create.content.logistics.depot.EjectorBlock.HORIZONTAL_FACING,Direction.EAST));
        var ejector=h.getBlockEntity(S,com.simibubi.create.content.logistics.depot.EjectorBlockEntity.class);ejector.setMinimumStackSize(64);h.setBlock(S.east(),Blocks.REDSTONE_BLOCK);
        h.setBlock(S.south(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(com.simibubi.create.content.kinetics.motor.CreativeMotorBlock.FACING,Direction.NORTH));h.getBlockEntity(S.south(),com.simibubi.create.content.kinetics.base.KineticBlockEntity.class).setGeneratedSpeed(64);
        h.startSequence().thenWaitUntil(()->h.assertValueEqual(ejector.getState(),com.simibubi.create.content.logistics.depot.EjectorBlockEntity.State.CHARGED,"Actual source merging target naturally charges from its real connected motor"))
                .thenExecute(()->{
                    try(var tx=Transaction.openOuter()){h.assertValueEqual(ejector.depotBehaviour.itemHandler.insert(ItemVariant.of(Items.APPLE),62,tx),62L,"Only genuine Ejector source merging owns partial-capacity fixture");tx.commit();}
                    tunnel.updateTunnelConnections();insert(tunnel,Items.APPLE,10);tick(tunnel,3);
                    long owned=ejector.depotBehaviour.getHeldItemStack().getCount()+ejector.depotBehaviour.getIncomingItems().stream().mapToLong(item->item.stack.getCount()).sum();
                    h.assertValueEqual(owned,64L,"Actual held plus still-incoming owners fill source64 capacity");h.assertValueEqual(count(h,N,Items.APPLE),8L,"Actual remainder is redistributed to ordinary empty depot");h.assertValueEqual(owned+count(h,N,Items.APPLE),72L,"All original62+10 apples remain in real owners");h.assertTrue(tunnel.getStackToDistribute().isEmpty(),"No second queue owner after actual transfer");
                }).thenSucceed();
    }
    @GameTest public void forcedSplitWaitsUntilAllOutputsCanAccept(GameTestHelper h){var tunnel=cross(h);tunnel.setSelectionMode(SelectionMode.FORCED_SPLIT);fill(h,S,64);insert(tunnel,Items.APPLE,10);tick(tunnel,3);h.assertValueEqual(count(h,N,Items.APPLE),0L,"No partial forced distribution");h.assertValueEqual(tunnel.getStackToDistribute().getCount(),10,"Whole queue waits");var depot=h.getBlockEntity(S,DepotBlockEntity.class);try(var tx=Transaction.openOuter()){depot.inventory.inputs.getFirst().extract(ItemVariant.of(Items.APPLE),64,tx);tx.commit();}tick(tunnel,14);h.assertValueEqual(count(h,N,Items.APPLE),5L,"Resumed balanced distribution");h.assertValueEqual(count(h,S,Items.APPLE),5L,"Blocked output resumed");h.succeed();}
    @GameTest public void roundRobinRotatesWholeStacksAcrossOutputs(GameTestHelper h){var tunnel=cross(h);tunnel.setSelectionMode(SelectionMode.ROUND_ROBIN);insert(tunnel,Items.APPLE,8);tick(tunnel,3);insert(tunnel,Items.APPLE,6);tick(tunnel,3);h.assertValueEqual(count(h,S,Items.APPLE),8L,"First stack to first output");h.assertValueEqual(count(h,N,Items.APPLE),6L,"Second stack to next output");h.succeed();}
    @GameTest public void roundRobinSkipsBlockedOutputOnNextAttempt(GameTestHelper h){var tunnel=cross(h);tunnel.setSelectionMode(SelectionMode.ROUND_ROBIN);fill(h,S,64);insert(tunnel,Items.APPLE,8);tick(tunnel,3);h.assertValueEqual(tunnel.getStackToDistribute().getCount(),8,"Current round blocked");tick(tunnel,14);h.assertValueEqual(count(h,N,Items.APPLE),8L,"Next round skips full destination");h.succeed();}
    @GameTest public void forcedRoundRobinRetainsCurrentOutputUntilItBecomesAvailable(GameTestHelper h){var tunnel=cross(h);tunnel.setSelectionMode(SelectionMode.FORCED_ROUND_ROBIN);fill(h,S,64);insert(tunnel,Items.APPLE,8);tick(tunnel,40);h.assertValueEqual(count(h,N,Items.APPLE),0L,"Other output cannot steal forced turn");h.assertValueEqual(tunnel.getStackToDistribute().getCount(),8,"Queue retained");h.succeed();}
    @GameTest public void nearestPrefersOwnSideAndRandomizedOutputConservesContents(GameTestHelper h){var tunnel=cross(h);tunnel.setSelectionMode(SelectionMode.PREFER_NEAREST);insert(tunnel,Items.APPLE,9);tick(tunnel,3);h.assertValueEqual(count(h,S,Items.APPLE),9L,"First own side selected");tunnel.setSelectionMode(SelectionMode.RANDOMIZE);insert(tunnel,Items.CARROT,13);tick(tunnel,3);h.assertValueEqual(count(h,N,Items.CARROT)+count(h,S,Items.CARROT),13L,"Random output neither duplicates nor drops");h.succeed();}
    @GameTest public void filteredOutputsTakePrecedenceAndInputFilterCanBlockCargo(GameTestHelper h){var tunnel=cross(h);tunnel.filtering.setFilter(Direction.NORTH,FilterGameTests.filter(false,false,new ItemStack(Items.APPLE)));insert(tunnel,Items.APPLE,12);tick(tunnel,3);h.assertValueEqual(count(h,N,Items.APPLE),12L,"Matching filtered output gets whole batch before unfiltered");h.assertValueEqual(count(h,S,Items.APPLE),0L,"Unfiltered destination waits");tunnel.filtering.setFilter(Direction.WEST,new ItemStack(Items.CARROT));h.assertFalse(tunnel.canInsert(Direction.WEST,new ItemStack(Items.APPLE)),"Input sample blocks unlisted cargo");h.succeed();}
    @GameTest public void abortedInputDoesNotOccupyQueueOrAnimateFlaps(GameTestHelper h){var tunnel=cross(h);float flap=tunnel.flaps.get(Direction.WEST).value(1);try(var outer=Transaction.openOuter()){try(var inner=outer.openNested()){h.assertValueEqual(tunnel.accept(new ItemStack(Items.APPLE,12),Direction.WEST,inner),12L,"Nested queue accepted");inner.commit();}}h.assertTrue(tunnel.getStackToDistribute().isEmpty()&&tunnel.canTakeItems(),"Outer abort frees queue");h.assertValueEqual(tunnel.flaps.get(Direction.WEST).value(1),flap,"No aborted flap animation");h.succeed();}
    @GameTest public void queueFilterModeAndInFlightTargetsSurviveNativeSaveLoad(GameTestHelper h){var tunnel=cross(h);tunnel.filtering.setFilter(Direction.NORTH,new ItemStack(Items.CARROT));tunnel.setSelectionMode(SelectionMode.PREFER_NEAREST);insert(tunnel,Items.APPLE,7);tick(tunnel,1);var restored=(BrassTunnelBlockEntity)BlockEntity.loadStatic(tunnel.getBlockPos(),tunnel.getBlockState(),tunnel.saveWithFullMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertValueEqual(restored.getStackToDistribute().getCount(),7,"Queue saved");h.assertValueEqual(restored.distributionProgress,2,"In-flight timer saved");h.assertValueEqual(restored.getSelectionMode(),SelectionMode.PREFER_NEAREST,"Mode saved");h.assertTrue(restored.filtering.getFilter(Direction.NORTH).is(Items.CARROT),"Side sample saved");h.getLevel().removeBlockEntity(tunnel.getBlockPos());h.getLevel().setBlockEntity(restored);tick(restored,2);h.assertValueEqual(count(h,S,Items.APPLE),7L,"Restored batch reaches its saved destination once");h.succeed();}
    @GameTest public void destroyingTunnelDropsQueueAndEachInstalledFilterExactlyOnce(GameTestHelper h){var tunnel=cross(h);tunnel.filtering.setFilter(Direction.NORTH,FilterGameTests.filter(false,false,new ItemStack(Items.APPLE)));insert(tunnel,Items.APPLE,17);h.setBlock(P,Blocks.AIR);var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(P)).inflate(1));h.assertValueEqual(drops.stream().filter(item->item.getItem().is(Items.APPLE)).mapToInt(item->item.getItem().getCount()).sum(),17,"One owned queue drop");h.assertValueEqual(drops.stream().filter(item->item.getItem().is(AllItems.FILTER)).mapToInt(item->item.getItem().getCount()).sum(),1,"One installed filter drop");h.succeed();}
    @GameTest public void andesiteBranchesOnePerSideLeavingAtLeastOneOnMainBelt(GameTestHelper h){var belt=chain(h,3);h.setBlock(N,AllBlocks.DEPOT);h.setBlock(S,AllBlocks.DEPOT);h.setBlock(P,AllBlocks.ANDESITE_TUNNEL.defaultBlockState().setValue(BeltTunnelBlock.HORIZONTAL_AXIS,Direction.Axis.X).setValue(BeltTunnelBlock.SHAPE,BeltTunnelBlock.Shape.CROSS));var tunnel=h.getBlockEntity(P,BeltTunnelBlockEntity.class);tunnel.updateTunnelConnections();try(var tx=Transaction.openOuter()){belt.getInventory().segment(1,Direction.UP).insert(ItemVariant.of(Items.APPLE),8,tx);tx.commit();}var item=belt.getInventory().getTransportedItems().getFirst();float next=BeltTunnelInteractionHandler.checkForTunnels(belt,belt.getInventory(),item,2.1f);h.assertValueEqual(next,2.1f,"Cargo crossed boundary");h.assertValueEqual(count(h,N,Items.APPLE),1L,"One north");h.assertValueEqual(count(h,S,Items.APPLE),1L,"One south");h.assertValueEqual(belt.getInventory().byId(item.id).stack.getCount(),6,"Six retained on main belt");h.succeed();}
    @GameTest public void andesiteBackpressurePreservesEarlierBranchesAndRetainsRemainingCargo(GameTestHelper h){var belt=chain(h,3);h.setBlock(N,AllBlocks.DEPOT);h.setBlock(S,AllBlocks.DEPOT);fill(h,N,64);h.setBlock(P,AllBlocks.ANDESITE_TUNNEL.defaultBlockState().setValue(BeltTunnelBlock.HORIZONTAL_AXIS,Direction.Axis.X).setValue(BeltTunnelBlock.SHAPE,BeltTunnelBlock.Shape.CROSS));h.getBlockEntity(P,BeltTunnelBlockEntity.class).updateTunnelConnections();try(var tx=Transaction.openOuter()){belt.getInventory().segment(1,Direction.UP).insert(ItemVariant.of(Items.APPLE),8,tx);tx.commit();}var item=belt.getInventory().getTransportedItems().getFirst();h.assertValueEqual(BeltTunnelInteractionHandler.checkForTunnels(belt,belt.getInventory(),item,2.1f),1.99f,"Cargo stops before entry");h.assertValueEqual(count(h,S,Items.APPLE),1L,"Earlier side commits before later blockage");h.assertValueEqual(belt.getInventory().byId(item.id).stack.getCount(),7,"Remaining cargo retained at blocked entry");h.succeed();}
    @GameTest public void sideInsertionIntoBrassBeltStorageEntersQueueAndRejectsSecondStack(GameTestHelper h){var tunnel=cross(h);var belt=h.getBlockEntity(new BlockPos(1,2,3),BeltBlockEntity.class);try(var tx=Transaction.openOuter()){h.assertValueEqual(belt.getInventory().segment(2,Direction.UP).insert(ItemVariant.of(Items.APPLE),12,tx),12L,"Insertion routed to queue");tx.commit();}h.assertValueEqual(tunnel.getStackToDistribute().getCount(),12,"Queue owns cargo");h.assertTrue(belt.getInventory().getTransportedItems().isEmpty(),"No second copy on belt");try(var tx=Transaction.openOuter()){h.assertValueEqual(belt.getInventory().segment(2,Direction.UP).insert(ItemVariant.of(Items.APPLE),1,tx),0L,"Queue full");}h.succeed();}
    @GameTest public void naturalShapesTrackOutputsAndHiddenFlaps(GameTestHelper h){chain(h,3);var block=AllBlocks.ANDESITE_TUNNEL;var world=h.getLevel();var pos=h.absolutePos(P);h.assertValueEqual(block.getTunnelState(world,pos).getValue(BeltTunnelBlock.SHAPE),BeltTunnelBlock.Shape.STRAIGHT,"No lateral output");h.setBlock(N,AllBlocks.DEPOT);h.assertValueEqual(block.getTunnelState(world,pos).getValue(BeltTunnelBlock.SHAPE),BeltTunnelBlock.Shape.T_RIGHT,"North branch on X belt");h.setBlock(S,AllBlocks.DEPOT);h.assertValueEqual(block.getTunnelState(world,pos).getValue(BeltTunnelBlock.SHAPE),BeltTunnelBlock.Shape.CROSS,"Both branches");h.succeed();}
    @GameTest public void heldModePacketsEnforceDistanceRangeAndDistributionSupport(GameTestHelper h){var tunnel=cross(h);var player=h.makeMockPlayer(GameType.SURVIVAL);var pos=h.absolutePos(P);player.setPos(Vec3.atCenterOf(pos).add(0,1,1));h.assertTrue(TunnelSettings.apply(h.getLevel(),player,new TunnelSettings.SetMode(pos,3)),"Nearby mode selection");h.assertValueEqual(tunnel.getSelectionMode(),SelectionMode.FORCED_ROUND_ROBIN,"Mode applied");h.assertFalse(TunnelSettings.apply(h.getLevel(),player,new TunnelSettings.SetMode(pos,7)),"Unknown mode ignored");player.setPos(Vec3.atCenterOf(pos).add(0,0,100));h.assertFalse(TunnelSettings.apply(h.getLevel(),player,new TunnelSettings.SetMode(pos,0)),"Remote packet rejected");h.succeed();}
    @GameTest public void tunnelItemPlacesOnBareBeltAndAddsMatchingCasing(GameTestHelper h){
        chain(h,3);var belt=h.getBlockEntity(P.below(),BeltBlockEntity.class);belt.setCasingType(BeltBlockEntity.CasingType.NONE);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,0,2));player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllBlocks.BRASS_TUNNEL,2));var support=h.absolutePos(P.below());var hit=new BlockHitResult(new Vec3(support.getX()+.5,support.getY()+1,support.getZ()+.5),Direction.UP,support,false);var result=player.getMainHandItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,hit));h.assertTrue(result.consumesAction(),"Placement succeeded on bare belt");h.assertTrue(h.getBlockState(P).is(AllBlocks.BRASS_TUNNEL),"Tunnel placed");h.assertValueEqual(belt.getCasingType(),BeltBlockEntity.CasingType.BRASS,"Brass casing added");h.assertValueEqual(player.getMainHandItem().getCount(),1,"One tunnel item consumed");h.succeed();
    }
    @GameTest(maxTicks=90) public void actualMovingBeltCapturesAndDistributesCargoExactlyOnce(GameTestHelper h){
        var tunnel=cross(h);tunnel.setSelectionMode(SelectionMode.SPLIT);var motorPos=new BlockPos(1,2,2);h.setBlock(motorPos,AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(com.simibubi.create.content.kinetics.motor.CreativeMotorBlock.FACING,Direction.SOUTH));h.getBlockEntity(motorPos,com.simibubi.create.content.kinetics.base.KineticBlockEntity.class).setGeneratedSpeed(-64);var belt=h.getBlockEntity(new BlockPos(1,2,3),BeltBlockEntity.class);try(var tx=Transaction.openOuter()){belt.getInventory().segment(0,Direction.UP).insert(ItemVariant.of(Items.APPLE),11,tx);tx.commit();}
        h.succeedWhen(()->{h.assertValueEqual(count(h,N,Items.APPLE)+count(h,S,Items.APPLE),11L,"Live belt handed its cargo to the distribution queue");h.assertTrue(tunnel.getStackToDistribute().isEmpty()&&belt.getInventory().getTransportedItems().isEmpty(),"No second copy retained");});
    }
    @GameTest public void connectedTunnelModesPropagateAndSynchronizationWaitsForEveryLane(GameTestHelper h){
        chain(h,3);chain(h,4);for(int z=3;z<=4;z++){h.setBlock(new BlockPos(4,2,z),AllBlocks.DEPOT);h.setBlock(new BlockPos(3,3,z),AllBlocks.BRASS_TUNNEL.defaultBlockState().setValue(BeltTunnelBlock.HORIZONTAL_AXIS,Direction.Axis.X));}
        var first=h.getBlockEntity(P,BrassTunnelBlockEntity.class);var second=h.getBlockEntity(P.south(),BrassTunnelBlockEntity.class);for(int i=0;i<3;i++){first.updateTunnelConnections();second.updateTunnelConnections();}h.assertTrue(first.isConnected(false)&&second.isConnected(true),"Parallel lanes connected");first.setSelectionMode(SelectionMode.SYNCHRONIZE);h.assertValueEqual(second.getSelectionMode(),SelectionMode.SYNCHRONIZE,"Setting propagated");insert(first,Items.APPLE,8);tick(first,20);h.assertValueEqual(first.getStackToDistribute().getCount(),8,"One lane waits for other");insert(second,Items.CARROT,6);for(int i=0;i<5;i++){first.tickDistribution();second.tickDistribution();}h.assertTrue(first.getStackToDistribute().isEmpty()&&second.getStackToDistribute().isEmpty(),"Synchronized group released");h.assertValueEqual(count(h,new BlockPos(4,2,3),Items.APPLE)+count(h,new BlockPos(4,2,4),Items.APPLE),8L,"Apples conserved across group");h.assertValueEqual(count(h,new BlockPos(4,2,3),Items.CARROT)+count(h,new BlockPos(4,2,4),Items.CARROT),6L,"Carrots conserved across group");h.succeed();
    }
}
